export function toShowdownId(text) {
  return String(text || "").toLowerCase().replace(/[^a-z0-9]+/g, "");
}

export function getMoveTextEs(nameOrId) {
  const raw = String(nameOrId || "").trim();
  const clean = raw.startsWith("MT ") ? raw.slice(3).trim() : raw;
  const id = toShowdownId(clean);
  const entry = SHOWDOWN_TEXT_ES.moves[id];
  return {
    id,
    en: entry?.en || clean,
    es: entry?.es || clean,
    desc: entry?.desc || "",
  };
}

export function getAbilityTextEs(nameOrId) {
  const raw = String(nameOrId || "").trim();
  const id = toShowdownId(raw);
  const entry = SHOWDOWN_TEXT_ES.abilities[id];
  return {
    id,
    en: entry?.en || raw,
    es: entry?.es || raw,
    desc: entry?.desc || "",
  };
}

export function getItemTextEs(nameOrId) {
  const raw = String(nameOrId || "").trim();
  if (raw.startsWith("MT ")) {
    const mv = getMoveTextEs(raw.slice(3));
    return {
      id: mv.id,
      en: raw,
      es: `MT ${mv.es}`,
      desc: mv.desc ? `Enseña ${mv.es}: ${mv.desc}` : "",
    };
  }
  const id = toShowdownId(raw);
  const entry = SHOWDOWN_TEXT_ES.items[id];
  return {
    id,
    en: entry?.en || raw,
    es: entry?.es || raw,
    desc: entry?.desc || "",
  };
}

if (typeof window !== "undefined") {
  window.SHOWDOWN_TEXT_ES = SHOWDOWN_TEXT_ES;
  window.getMoveTextEs = getMoveTextEs;
  window.getAbilityTextEs = getAbilityTextEs;
  window.getItemTextEs = getItemTextEs;
}
